#define _GNU_SOURCE
#include <dlfcn.h>
#include <string.h>
#include <unistd.h>

ssize_t readlink(const char *path, char *buffer, size_t size) {
  static ssize_t (*system_readlink)(const char *, char *, size_t);
  if (!system_readlink)
    system_readlink = dlsym(RTLD_NEXT, "readlink");

  if (strncmp(path, "/proc/", 6) == 0) {
    const char *suffix = strrchr(path, '/');
    if (suffix && strcmp(suffix, "/exe") == 0)
      path = "/proc/self/exe";
  }

  return system_readlink(path, buffer, size);
}

